def is_decimal(text):
    # 2500, 2500.50 and -10 are numbers; '', '1e3', '.5' and 'abc' are not.
    if text.startswith('-'):
        text = text[1:]
    parts = text.split('.')
    return len(parts) <= 2 and all(p and all(c in '0123456789' for c in p) for p in parts)


def is_count(text):
    # offset and limit: a whole number >= 0, so '-1' and '1.5' fail.
    return text != '' and all(c in '0123456789' for c in text)


def solution(users, params):
    # 1. Validate in a fixed order, so the first illegal param is predictable.
    lo = params.get('min', '0')
    if not is_decimal(lo):
        return {'error': 'min'}
    hi = params.get('max', '4000')
    if not is_decimal(hi) or float(hi) < float(lo):
        return {'error': 'max'}
    offset = params.get('offset', '0')
    if not is_count(offset):
        return {'error': 'offset'}
    limit = params.get('limit')                     # None means "no limit"
    if limit is not None and not is_count(limit):
        return {'error': 'limit'}
    sort = params.get('sort')
    if sort is not None and sort.upper() not in ('NAME', 'SALARY'):
        return {'error': 'sort'}

    # 2. Filter, 3. sort (ties by name), 4. page.
    lo, hi = float(lo), float(hi)
    rows = [[name, salary] for name, salary in users if lo <= salary <= hi]
    if sort is not None and sort.upper() == 'NAME':
        rows.sort(key=lambda r: r[0])
    elif sort is not None:
        rows.sort(key=lambda r: (r[1], r[0]))
    start = int(offset)
    end = None if limit is None else start + int(limit)
    return {'results': rows[start:end]}

