def solution(users, params):
    # Same rules, longhand: try/except parsing and an insertion sort.
    def number(text):
        # float() alone is too lenient ('1e3', 'nan', '1_000', ' 5'), so whitelist characters first.
        if text == '' or any(c not in '0123456789.-' for c in text):
            return None
        if text.startswith('.') or text.endswith('.') or text.startswith('-.'):
            return None
        try:
            return float(text)
        except ValueError:
            return None
    lo = number(params['min']) if 'min' in params else 0.0
    if lo is None:
        return {'error': 'min'}
    hi = number(params['max']) if 'max' in params else 4000.0
    if hi is None or hi < lo:
        return {'error': 'max'}
    counts = {}
    for key in ('offset', 'limit'):
        if key in params:
            text = params[key]
            if text == '' or any(c not in '0123456789' for c in text):
                return {'error': key}
            counts[key] = int(text)
    mode = None
    if 'sort' in params:
        mode = params['sort'].lower()
        if mode not in ('name', 'salary'):
            return {'error': 'sort'}
    picked = []
    for u in users:
        if u[1] >= lo and u[1] <= hi:
            picked.append([u[0], u[1]])
    if mode is not None:
        for i in range(1, len(picked)):
            j = i
            while j > 0:
                a, b = picked[j - 1], picked[j]
                if mode == 'name':
                    swap = a[0] > b[0]
                else:
                    swap = a[1] > b[1] or (a[1] == b[1] and a[0] > b[0])
                if not swap:
                    break
                picked[j - 1], picked[j] = b, a
                j -= 1
    start = counts.get('offset', 0)
    out = picked[start:]
    if 'limit' in counts:
        out = out[:counts['limit']]
    return {'results': out}
